CREATE OR REPLACE FUNCTION app.accept_workspace_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
  v_hash text;
  v_invite public.workspace_invites;
  v_user_email text;
BEGIN
  v_uid := app.require_confirmed_email();
  v_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');

  SELECT *
    INTO v_invite
  FROM public.workspace_invites i
  WHERE i.token_hash = v_hash
  FOR UPDATE;

  IF v_invite.id IS NULL THEN
    RAISE EXCEPTION 'invite_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_invite.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'invite_revoked' USING ERRCODE = 'P0001';
  END IF;
  IF v_invite.accepted_at IS NOT NULL THEN
    RAISE EXCEPTION 'invite_already_accepted' USING ERRCODE = 'P0001';
  END IF;
  IF v_invite.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'invite_expired' USING ERRCODE = 'P0001';
  END IF;

  SELECT lower(btrim(u.email))
    INTO v_user_email
  FROM auth.users u
  WHERE u.id = v_uid;

  IF v_invite.email IS NOT NULL AND v_user_email IS DISTINCT FROM v_invite.email THEN
    RAISE EXCEPTION 'invite_email_mismatch' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.workspace_members m
    WHERE m.workspace_id = v_invite.workspace_id
      AND m.user_id = v_uid
  ) THEN
    RAISE EXCEPTION 'already_a_member' USING ERRCODE = 'P0001';
  END IF;

  IF v_invite.role IN ('admin', 'professional') THEN
    PERFORM app.assert_professional_seat_available(v_invite.workspace_id);
  ELSE
    PERFORM app.lock_workspace_billing(v_invite.workspace_id);
  END IF;

  PERFORM set_config('app.bypass_protected_columns', 'on', true);

  INSERT INTO public.workspace_members (workspace_id, user_id, role, status)
  VALUES (v_invite.workspace_id, v_uid, v_invite.role, 'active');

  UPDATE public.workspace_invites
  SET accepted_at = clock_timestamp(),
      accepted_by = v_uid,
      updated_at = clock_timestamp()
  WHERE id = v_invite.id;

  RETURN jsonb_build_object(
    'workspace_id', v_invite.workspace_id,
    'role', v_invite.role
  );
END;
$function$

CREATE OR REPLACE FUNCTION app.actor_member(p_workspace_id uuid)
 RETURNS workspace_members
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_row public.workspace_members;
begin
  perform app.assert_workspace_entitled(p_workspace_id);

  select m.* into v_row
  from public.workspace_members m
  where m.workspace_id = p_workspace_id
    and m.user_id = auth.uid()
    and m.status = 'active';

  if v_row.id is null then
    raise exception 'not_workspace_member' using errcode = '42501';
  end if;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION app.allocate_workspace_slug(p_name text, p_slug text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_base text;
  v_slug text;
  v_suffix integer := 2;
BEGIN
  IF p_slug IS NOT NULL AND length(trim(p_slug)) > 0 THEN
    v_base := app.slugify(p_slug);
  ELSE
    v_base := app.slugify(p_name);
  END IF;

  IF v_base IS NULL OR char_length(v_base) < 3 THEN
    v_base := 'negocio-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
  END IF;

  IF char_length(v_base) > 50 THEN
    v_base := substr(v_base, 1, 50);
    v_base := trim(both '-' FROM v_base);
  END IF;

  v_slug := v_base;
  WHILE EXISTS (SELECT 1 FROM public.workspaces w WHERE w.slug = v_slug)
     OR app.is_reserved_workspace_slug(v_slug)
  LOOP
    v_slug := v_base || '-' || v_suffix::text;
    v_suffix := v_suffix + 1;
  END LOOP;

  RETURN v_slug;
END;
$function$

CREATE OR REPLACE FUNCTION app.apply_inventory_movement(p_workspace_id uuid, p_product_id uuid, p_type inventory_movement_type, p_quantity numeric DEFAULT NULL::numeric, p_new_quantity numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_product public.inventory_products;
  v_before numeric(12, 3);
  v_after numeric(12, 3);
  v_qty numeric(12, 3);
  v_reason text;
  v_movement_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
  END IF;
  PERFORM app.assert_inventory_mover(p_workspace_id, p_type);
  v_product := app.lock_inventory_product(p_workspace_id, p_product_id);
  IF v_product.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'inventory_product_archived' USING ERRCODE = '42501';
  END IF;
  v_before := v_product.quantity;
  v_reason := nullif(btrim(COALESCE(p_reason, '')), '');
  IF p_type = 'adjustment'::public.inventory_movement_type THEN
    v_after := app.normalize_inventory_quantity(p_new_quantity);
    v_qty := abs(v_after - v_before);
  ELSE
    v_qty := app.normalize_inventory_quantity(p_quantity);
    IF v_qty <= 0 THEN
      RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
    END IF;
    IF p_type = 'entry'::public.inventory_movement_type THEN
      v_after := v_before + v_qty;
    ELSE
      v_after := v_before - v_qty;
    END IF;
  END IF;
  IF v_after < 0 THEN
    RAISE EXCEPTION 'insufficient_stock' USING ERRCODE = 'P0001';
  END IF;
  v_after := app.normalize_inventory_quantity(v_after);
  PERFORM set_config('app.inventory_mutating', 'on', true);
  UPDATE public.inventory_products SET quantity = v_after
  WHERE id = v_product.id AND workspace_id = v_product.workspace_id;
  INSERT INTO public.inventory_movements (
    workspace_id, product_id, type, quantity, quantity_before, quantity_after, reason, created_by
  ) VALUES (
    v_product.workspace_id, v_product.id, p_type, v_qty, v_before, v_after, v_reason, auth.uid()
  ) RETURNING id INTO v_movement_id;
  PERFORM set_config('app.inventory_mutating', 'off', true);
  RETURN jsonb_build_object(
    'movement_id', v_movement_id,
    'product_id', v_product.id,
    'type', p_type,
    'quantity', v_qty,
    'quantity_before', v_before,
    'quantity_after', v_after
  );
END;
$function$

CREATE OR REPLACE FUNCTION app.appointments_assert_availability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.starts_at IS NOT DISTINCT FROM OLD.starts_at
     AND NEW.ends_at IS NOT DISTINCT FROM OLD.ends_at
     AND NEW.professional_member_id IS NOT DISTINCT FROM OLD.professional_member_id
     AND NEW.service_id IS NOT DISTINCT FROM OLD.service_id THEN
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN (
    'scheduled'::public.appointment_status,
    'confirmed'::public.appointment_status,
    'in_progress'::public.appointment_status
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM app.lock_professional_agenda(NEW.professional_member_id);
  PERFORM app.assert_slot_available(
    NEW.workspace_id,
    NEW.professional_member_id,
    NEW.starts_at,
    NEW.ends_at,
    CASE WHEN TG_OP = 'UPDATE' THEN NEW.id ELSE NULL END
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.archive_financial_category(p_workspace_id uuid, p_category_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_system_key text;
begin
  perform app.assert_finance_manager(p_workspace_id);

  select system_key into v_system_key
  from public.financial_categories
  where id=p_category_id and workspace_id=p_workspace_id
  for update;

  if not found then
    raise exception 'financial_category_not_found' using errcode='P0002';
  end if;

  if v_system_key is not null then
    raise exception 'system_category_cannot_be_archived' using errcode='22023';
  end if;

  update public.financial_categories
  set active=false,archived_at=now()
  where id=p_category_id and workspace_id=p_workspace_id;

  return p_category_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.archive_inventory_product(p_workspace_id uuid, p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_product public.inventory_products;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
  END IF;
  PERFORM app.assert_inventory_manager(p_workspace_id);
  PERFORM app.lock_inventory_product(p_workspace_id, p_product_id);
  UPDATE public.inventory_products SET archived_at = COALESCE(archived_at, clock_timestamp()), active = false
  WHERE id = p_product_id AND workspace_id = p_workspace_id
  RETURNING * INTO v_product;
  RETURN jsonb_build_object('id', v_product.id, 'archived_at', v_product.archived_at);
END;
$function$

CREATE OR REPLACE FUNCTION app.archive_service_package(p_workspace_id uuid, p_package_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app.assert_package_manager(p_workspace_id);
  update public.service_packages set archived_at=coalesce(archived_at,clock_timestamp()),active=false
  where id=p_package_id and workspace_id=p_workspace_id;
  if not found then raise exception 'package_not_found' using errcode='P0002'; end if;
  return p_package_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.assert_finance_manager(p_workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app.require_confirmed_email();
  perform app.assert_workspace_entitled(p_workspace_id);

  if not app.has_workspace_role(
    p_workspace_id,
    variadic array['owner'::public.member_role,'admin'::public.member_role]
  ) then
    raise exception 'not_authorized' using errcode='42501';
  end if;
end;
$function$

