CREATE OR REPLACE FUNCTION app.assert_financial_category(p_workspace_id uuid, p_category_id uuid, p_entry_type financial_entry_type)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_category_id is null then return; end if;

  if not exists(
    select 1 from public.financial_categories c
    where c.id=p_category_id
      and c.workspace_id=p_workspace_id
      and c.entry_type=p_entry_type
      and c.active
      and c.archived_at is null
  ) then
    raise exception 'invalid_financial_category' using errcode='22023';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION app.assert_inventory_manager(p_workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app.assert_workspace_entitled(p_workspace_id);
  if not app.has_workspace_role(
    p_workspace_id,
    variadic array['owner'::public.member_role, 'admin'::public.member_role]
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION app.assert_inventory_mover(p_workspace_id uuid, p_type inventory_movement_type)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app.assert_workspace_entitled(p_workspace_id);

  if p_type = 'adjustment'::public.inventory_movement_type then
    perform app.assert_inventory_manager(p_workspace_id);
    return;
  end if;

  if not app.has_workspace_role(
    p_workspace_id,
    variadic array[
      'owner'::public.member_role,
      'admin'::public.member_role,
      'receptionist'::public.member_role
    ]
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION app.assert_member_change_allowed(p_workspace_id uuid, p_member workspace_members, p_next_role member_role, p_next_status member_status)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM app.lock_workspace_membership(p_workspace_id);
  IF p_member.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF p_next_role = 'owner'::public.member_role AND p_member.role IS DISTINCT FROM 'owner'::public.member_role THEN
    RAISE EXCEPTION 'owner_transfer_not_supported' USING ERRCODE = '42501';
  END IF;
  IF p_member.role = 'owner'::public.member_role
     AND p_member.status = 'active'::public.member_status
     AND (
       p_next_role IS DISTINCT FROM 'owner'::public.member_role
       OR p_next_status IS DISTINCT FROM 'active'::public.member_status
     )
     AND app.active_owner_count(p_workspace_id) <= 1 THEN
    RAISE EXCEPTION 'last_owner_protected' USING ERRCODE = 'P0001';
  END IF;
END;
$function$

