CREATE OR REPLACE FUNCTION app.assert_professional_seat_available(p_workspace_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_plan public.plans;
  v_seats integer;
BEGIN
  PERFORM app.lock_workspace_billing(p_workspace_id);

  SELECT p.*
    INTO v_plan
  FROM public.subscriptions s
  JOIN public.plans p ON p.code = s.plan
  WHERE s.workspace_id = p_workspace_id;

  v_seats := app.workspace_professional_seats(p_workspace_id);
  IF v_seats >= v_plan.max_professionals THEN
    RAISE EXCEPTION 'plan_professional_limit_reached' USING ERRCODE = 'P0001';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_public_booking_rate(p_workspace_id uuid, p_email text, p_phone text, p_ip_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_hour integer;
  v_day integer;
BEGIN
  SELECT count(*)::int INTO v_hour
  FROM public.public_booking_rate_events e
  WHERE e.workspace_id = p_workspace_id
    AND e.created_at > clock_timestamp() - interval '1 hour';
  IF v_hour >= app.public_booking_max_workspace_per_hour() THEN
    RAISE EXCEPTION 'booking_rate_limited' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*)::int INTO v_day
  FROM public.public_booking_rate_events e
  WHERE e.workspace_id = p_workspace_id
    AND e.created_at > clock_timestamp() - interval '24 hours';
  IF v_day >= app.public_booking_max_workspace_per_day() THEN
    RAISE EXCEPTION 'booking_rate_limited' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*)::int INTO v_hour
  FROM public.public_booking_rate_events e
  WHERE e.workspace_id = p_workspace_id
    AND e.created_at > clock_timestamp() - interval '1 hour'
    AND (
      (p_email IS NOT NULL AND e.email = p_email)
      OR (p_phone IS NOT NULL AND e.phone = p_phone)
      OR (p_ip_hash IS NOT NULL AND e.ip_hash = p_ip_hash)
    );
  IF v_hour >= app.public_booking_max_per_hour() THEN
    RAISE EXCEPTION 'booking_rate_limited' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*)::int INTO v_day
  FROM public.public_booking_rate_events e
  WHERE e.workspace_id = p_workspace_id
    AND e.created_at > clock_timestamp() - interval '24 hours'
    AND (
      (p_email IS NOT NULL AND e.email = p_email)
      OR (p_phone IS NOT NULL AND e.phone = p_phone)
      OR (p_ip_hash IS NOT NULL AND e.ip_hash = p_ip_hash)
    );
  IF v_day >= app.public_booking_max_per_day() THEN
    RAISE EXCEPTION 'booking_rate_limited' USING ERRCODE = 'P0001';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_public_booking_window(p_workspace_id uuid, p_starts_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_tz text := app.workspace_timezone(p_workspace_id);
  v_local_date date;
  v_today date;
BEGIN
  v_local_date := (p_starts_at AT TIME ZONE v_tz)::date;
  v_today := (clock_timestamp() AT TIME ZONE v_tz)::date;

  IF v_local_date < v_today THEN
    RAISE EXCEPTION 'slot_in_past' USING ERRCODE = '22023';
  END IF;
  IF v_local_date > v_today + app.booking_horizon_days() THEN
    RAISE EXCEPTION 'slot_too_far' USING ERRCODE = '22023';
  END IF;
  IF p_starts_at < clock_timestamp() + make_interval(mins => app.booking_min_lead_minutes()) THEN
    RAISE EXCEPTION 'slot_too_soon' USING ERRCODE = '22023';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_slot_available(p_workspace_id uuid, p_professional_member_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_ignore_appointment_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_tz text := app.workspace_timezone(p_workspace_id);
  v_local_start timestamp;
  v_local_end timestamp;
  v_dow integer;
  v_start_min integer;
  v_end_min integer;
  v_profile public.professional_profiles%ROWTYPE;
  v_member public.workspace_members%ROWTYPE;
BEGIN
  IF p_starts_at IS NULL OR p_ends_at IS NULL OR p_starts_at >= p_ends_at THEN
    RAISE EXCEPTION 'invalid_appointment_range' USING ERRCODE = '22023';
  END IF;

  v_local_start := p_starts_at AT TIME ZONE v_tz;
  v_local_end := p_ends_at AT TIME ZONE v_tz;
  v_start_min := app.time_to_minutes(v_local_start::time);
  v_end_min := app.time_to_minutes(v_local_end::time);

  IF v_local_end::date > v_local_start::date THEN
    v_end_min := v_end_min + 1440 * (v_local_end::date - v_local_start::date);
  END IF;

  IF v_end_min > 1440 THEN
    RAISE EXCEPTION 'appointment_crosses_local_date' USING ERRCODE = '22023';
  END IF;

  v_dow := EXTRACT(DOW FROM v_local_start)::integer;

  SELECT p.* INTO v_profile
  FROM public.professional_profiles p
  WHERE p.member_id = p_professional_member_id
    AND p.workspace_id = p_workspace_id;

  IF v_profile.member_id IS NULL THEN
    RAISE EXCEPTION 'professional_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_profile.booking_enabled IS NOT TRUE THEN
    RAISE EXCEPTION 'professional_booking_disabled' USING ERRCODE = '22023';
  END IF;

  SELECT m.* INTO v_member
  FROM public.workspace_members m
  WHERE m.id = p_professional_member_id
    AND m.workspace_id = p_workspace_id;

  IF v_member.id IS NULL OR v_member.status IS DISTINCT FROM 'active'::public.member_status THEN
    RAISE EXCEPTION 'professional_inactive' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.professional_working_hours h
    WHERE h.workspace_id = p_workspace_id
      AND h.professional_member_id = p_professional_member_id
      AND h.weekday = v_dow
      AND h.active
      AND app.time_to_minutes(h.start_time) <= v_start_min
      AND app.time_to_minutes(h.end_time) >= v_end_min
  ) THEN
    RAISE EXCEPTION 'outside_working_hours' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.professional_breaks b
    WHERE b.workspace_id = p_workspace_id
      AND b.professional_member_id = p_professional_member_id
      AND b.weekday = v_dow
      AND b.active
      AND int4range(app.time_to_minutes(b.start_time), app.time_to_minutes(b.end_time), '[)')
          && int4range(v_start_min, v_end_min, '[)')
  ) THEN
    RAISE EXCEPTION 'inside_break' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.professional_time_blocks blk
    WHERE blk.workspace_id = p_workspace_id
      AND blk.professional_member_id = p_professional_member_id
      AND tstzrange(blk.starts_at, blk.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)')
  ) THEN
    RAISE EXCEPTION 'inside_time_block' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.appointments a
    WHERE a.workspace_id = p_workspace_id
      AND a.professional_member_id = p_professional_member_id
      AND a.status IN (
        'scheduled'::public.appointment_status,
        'confirmed'::public.appointment_status,
        'in_progress'::public.appointment_status,
        'completed'::public.appointment_status
      )
      AND (p_ignore_appointment_id IS NULL OR a.id <> p_ignore_appointment_id)
      AND tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(p_starts_at, p_ends_at, '[)')
  ) THEN
    RAISE EXCEPTION 'appointment_overlap' USING ERRCODE = '23P01';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION app.assert_status_transition(p_from appointment_status, p_to appointment_status, p_role member_role)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
BEGIN
  IF p_from = p_to THEN
    RETURN;
  END IF;

  IF p_from IN (
    'completed'::public.appointment_status,
    'cancelled'::public.appointment_status,
    'no_show'::public.appointment_status
  ) THEN
    RAISE EXCEPTION 'appointment_terminal' USING ERRCODE = '22023';
  END IF;

  IF p_role = 'receptionist'::public.member_role THEN
    IF p_to NOT IN (
      'confirmed'::public.appointment_status,
      'cancelled'::public.appointment_status,
      'no_show'::public.appointment_status
    ) THEN
      RAISE EXCEPTION 'status_denied' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_from = 'scheduled'::public.appointment_status
     AND p_to IN (
       'confirmed'::public.appointment_status,
       'in_progress'::public.appointment_status,
       'cancelled'::public.appointment_status,
       'no_show'::public.appointment_status
     ) THEN
    RETURN;
  END IF;

  IF p_from = 'confirmed'::public.appointment_status
     AND p_to IN (
       'in_progress'::public.appointment_status,
       'cancelled'::public.appointment_status,
       'no_show'::public.appointment_status
     ) THEN
    RETURN;
  END IF;

  IF p_from = 'in_progress'::public.appointment_status
     AND p_to IN (
       'completed'::public.appointment_status,
       'cancelled'::public.appointment_status
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'invalid_status_transition' USING ERRCODE = '22023';
END;
$function$

CREATE OR REPLACE FUNCTION app.bind_billing_customer(p_workspace_id uuid, p_provider text, p_external_customer_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_subscription public.subscriptions%rowtype;
  v_provider text := lower(btrim(coalesce(p_provider, '')));
  v_customer_id text := btrim(coalesce(p_external_customer_id, ''));
begin
  if p_workspace_id is null then
    raise exception 'workspace_required' using errcode = '22023';
  end if;

  if v_provider <> 'stripe' then
    raise exception 'billing_provider_invalid' using errcode = '22023';
  end if;

  if v_customer_id = '' or char_length(v_customer_id) > 200 then
    raise exception 'external_customer_invalid' using errcode = '22023';
  end if;

  select *
    into v_subscription
  from public.subscriptions
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'subscription_missing' using errcode = 'P0001';
  end if;

  if v_subscription.billing_provider is not null
     and v_subscription.billing_provider <> v_provider then
    raise exception 'billing_provider_conflict' using errcode = 'P0001';
  end if;

  if v_subscription.external_customer_id is not null
     and v_subscription.external_customer_id <> v_customer_id then
    raise exception 'external_customer_conflict' using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from public.subscriptions s
    where s.workspace_id <> p_workspace_id
      and s.billing_provider = v_provider
      and s.external_customer_id = v_customer_id
  ) then
    raise exception 'external_customer_already_bound' using errcode = '23505';
  end if;

  perform set_config('app.bypass_protected_columns', 'on', true);

  update public.subscriptions
  set billing_provider = v_provider,
      external_customer_id = v_customer_id
  where workspace_id = p_workspace_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.bind_stripe_checkout(p_workspace_id uuid, p_payer_email text, p_external_customer_id text, p_external_subscription_id text, p_plan subscription_plan, p_billing_interval billing_interval, p_external_event_id text, p_event_type text, p_event_status text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text := lower(btrim(coalesce(p_payer_email, '')));
  v_customer_id text := btrim(coalesce(p_external_customer_id, ''));
  v_subscription_id text := btrim(coalesce(p_external_subscription_id, ''));
  v_max_professionals integer;
  v_used_professionals integer;
  v_subscription public.subscriptions%rowtype;
begin
  if p_workspace_id is null then
    raise exception 'workspace_required' using errcode = '22023';
  end if;

  if v_email = '' or char_length(v_email) > 320 then
    raise exception 'payer_email_invalid' using errcode = '22023';
  end if;

  if v_customer_id = '' or char_length(v_customer_id) > 200 then
    raise exception 'external_customer_invalid' using errcode = '22023';
  end if;

  if v_subscription_id = '' or char_length(v_subscription_id) > 200 then
    raise exception 'external_subscription_invalid' using errcode = '22023';
  end if;

  if p_plan is null or p_billing_interval is null then
    raise exception 'billing_state_required' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.workspace_members m
    join auth.users u on u.id = m.user_id
    where m.workspace_id = p_workspace_id
      and m.status = 'active'::public.member_status
      and m.role in ('owner'::public.member_role, 'admin'::public.member_role)
      and u.email_confirmed_at is not null
      and lower(u.email) = v_email
  ) then
    raise exception 'billing_payer_not_workspace_manager' using errcode = '42501';
  end if;

  select p.max_professionals
    into v_max_professionals
  from public.plans p
  where p.code = p_plan;

  if v_max_professionals is null then
    raise exception 'plan_not_found' using errcode = '22023';
  end if;

  v_used_professionals := app.workspace_professional_seats(p_workspace_id);
  if v_used_professionals > v_max_professionals then
    raise exception 'plan_seat_limit_exceeded' using errcode = '23514';
  end if;

  select *
    into v_subscription
  from public.subscriptions
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'subscription_missing' using errcode = 'P0001';
  end if;

  if v_subscription.billing_provider is not null
     and v_subscription.billing_provider <> 'stripe' then
    raise exception 'billing_provider_conflict' using errcode = 'P0001';
  end if;

  if v_subscription.external_customer_id is not null
     and v_subscription.external_customer_id <> v_customer_id then
    raise exception 'external_customer_conflict' using errcode = 'P0001';
  end if;

  if v_subscription.external_subscription_id is not null
     and v_subscription.external_subscription_id <> v_subscription_id
     and v_subscription.status not in (
       'canceled'::public.subscription_status,
       'expired'::public.subscription_status
     ) then
    raise exception 'external_subscription_conflict' using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from public.subscriptions s
    where s.workspace_id <> p_workspace_id
      and s.billing_provider = 'stripe'
      and (
        s.external_customer_id = v_customer_id
        or s.external_subscription_id = v_subscription_id
      )
  ) then
    raise exception 'external_billing_identity_already_bound' using errcode = '23505';
  end if;

  perform set_config('app.bypass_protected_columns', 'on', true);

  update public.subscriptions
  set plan = p_plan,
      billing_interval = p_billing_interval,
      billing_provider = 'stripe',
      external_customer_id = v_customer_id,
      external_subscription_id = v_subscription_id
  where workspace_id = p_workspace_id;

  perform app.record_billing_event(
    p_workspace_id,
    'stripe',
    p_external_event_id,
    p_event_type,
    null,
    'BRL',
    p_billing_interval,
    p_event_status,
    coalesce(p_occurred_at, now())
  );
end;
$function$

