CREATE OR REPLACE FUNCTION app.create_financial_entry(p_workspace_id uuid, p_entry_type financial_entry_type, p_description text, p_amount_cents integer, p_due_date date DEFAULT NULL::date, p_category_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_key text:=nullif(btrim(coalesce(p_idempotency_key,'')),'');
  v_existing public.financial_entries%rowtype;
begin
  perform app.assert_finance_manager(p_workspace_id);
  perform app.assert_financial_category(p_workspace_id,p_category_id,p_entry_type);

  if p_amount_cents is null or p_amount_cents<=0 or p_amount_cents>1000000000 then
    raise exception 'invalid_amount' using errcode='22023';
  end if;

  if v_key is not null and char_length(v_key) not between 8 and 120 then
    raise exception 'invalid_idempotency_key' using errcode='22023';
  end if;

  if v_key is not null then
    select * into v_existing
    from public.financial_entries
    where workspace_id=p_workspace_id
      and idempotency_key=v_key
    for update;

    if v_existing.id is not null then
      if v_existing.source<>'manual'::public.financial_entry_source
         or v_existing.entry_type<>p_entry_type
         or v_existing.description<>btrim(p_description)
         or v_existing.amount_cents<>p_amount_cents
         or v_existing.due_date is distinct from p_due_date
         or v_existing.category_id is distinct from p_category_id then
        raise exception 'idempotency_key_conflict' using errcode='22023';
      end if;
      return v_existing.id;
    end if;
  end if;

  begin
    insert into public.financial_entries(
      workspace_id,entry_type,status,source,description,amount_cents,
      due_date,category_id,idempotency_key,created_by
    ) values(
      p_workspace_id,p_entry_type,'pending','manual',btrim(p_description),p_amount_cents,
      p_due_date,p_category_id,v_key,auth.uid()
    )
    returning id into v_id;
  exception when unique_violation then
    if v_key is null then raise; end if;

    select * into v_existing
    from public.financial_entries
    where workspace_id=p_workspace_id
      and idempotency_key=v_key;

    if v_existing.id is null
       or v_existing.source<>'manual'::public.financial_entry_source
       or v_existing.entry_type<>p_entry_type
       or v_existing.description<>btrim(p_description)
       or v_existing.amount_cents<>p_amount_cents
       or v_existing.due_date is distinct from p_due_date
       or v_existing.category_id is distinct from p_category_id then
      raise exception 'idempotency_key_conflict' using errcode='22023';
    end if;

    return v_existing.id;
  end;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.create_inventory_product(p_workspace_id uuid, p_name text, p_description text DEFAULT NULL::text, p_sku text DEFAULT NULL::text, p_unit inventory_unit DEFAULT 'unidade'::inventory_unit, p_initial_quantity numeric DEFAULT 0, p_minimum_quantity numeric DEFAULT 0, p_cost_cents integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_product public.inventory_products;
  v_initial numeric(12, 3);
  v_movement jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
  END IF;
  PERFORM app.assert_inventory_manager(p_workspace_id);
  v_initial := app.normalize_inventory_quantity(COALESCE(p_initial_quantity, 0));
  INSERT INTO public.inventory_products (
    workspace_id, name, description, sku, unit, quantity, minimum_quantity, cost_cents, created_by
  ) VALUES (
    p_workspace_id, btrim(p_name), nullif(btrim(COALESCE(p_description, '')), ''),
    nullif(btrim(COALESCE(p_sku, '')), ''), p_unit, 0,
    app.normalize_inventory_quantity(COALESCE(p_minimum_quantity, 0)), p_cost_cents, auth.uid()
  ) RETURNING * INTO v_product;
  IF v_initial > 0 THEN
    v_movement := app.apply_inventory_movement(
      p_workspace_id, v_product.id, 'entry'::public.inventory_movement_type, v_initial, NULL, 'Quantidade inicial'
    );
  END IF;
  SELECT * INTO v_product FROM public.inventory_products WHERE id = v_product.id;
  RETURN jsonb_build_object(
    'id', v_product.id,
    'workspace_id', v_product.workspace_id,
    'name', v_product.name,
    'quantity', v_product.quantity,
    'unit', v_product.unit,
    'minimum_quantity', v_product.minimum_quantity,
    'initial_movement', v_movement
  );
END;
$function$

