  if p_price_cents is null or p_price_cents < 0 or p_price_cents > 100000000 then
    raise exception 'invalid_package_price' using errcode='22023';
  end if;
  if p_validity_days is not null and (p_validity_days < 1 or p_validity_days > 3650) then
    raise exception 'invalid_validity_days' using errcode='22023';
  end if;
  insert into public.service_packages(workspace_id,name,description,price_cents,validity_days,created_by)
  values(p_workspace_id,btrim(p_name),nullif(btrim(coalesce(p_description,'')),''),p_price_cents,p_validity_days,auth.uid())
  returning id into v_id;
  perform app.replace_service_package_items(p_workspace_id,v_id,p_items);
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.create_workspace(p_name text, p_slug text DEFAULT NULL::text, p_plan text DEFAULT 'solo'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
  v_name text;
  v_slug text;
  v_workspace public.workspaces;
  v_subscription public.subscriptions;
  v_trial_started boolean := false;
  v_now timestamptz;
  v_trial_end timestamptz;
BEGIN
  v_uid := app.require_confirmed_email();
  IF p_plan IS NULL OR p_plan NOT IN ('solo', 'equipe', 'salao') THEN
    RAISE EXCEPTION 'invalid_plan' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_uid::text, 0));
  v_now := clock_timestamp();
  v_name := btrim(p_name);

  IF v_name IS NULL OR char_length(v_name) < 2 OR char_length(v_name) > 80 THEN
    RAISE EXCEPTION 'invalid_workspace_name' USING ERRCODE = '22023';
  END IF;

  v_slug := app.allocate_workspace_slug(v_name, p_slug);

  PERFORM set_config('app.bypass_protected_columns', 'on', true);

  INSERT INTO public.workspaces (owner_user_id, name, slug)
  VALUES (v_uid, v_name, v_slug)
  RETURNING * INTO v_workspace;

  IF EXISTS (
    SELECT 1 FROM public.professional_trial_claims c WHERE c.user_id = v_uid
  ) THEN
    INSERT INTO public.subscriptions (
      workspace_id, plan, status, trial_started_at, trial_ends_at,
      current_period_start, current_period_end
    ) VALUES (
      v_workspace.id, p_plan::public.subscription_plan, 'expired', NULL, NULL, NULL, NULL
    )
    RETURNING * INTO v_subscription;
  ELSE
    v_trial_end := v_now + interval '168 hours';
    INSERT INTO public.subscriptions (
      workspace_id, plan, status, trial_started_at, trial_ends_at,
      current_period_start, current_period_end
    ) VALUES (
      v_workspace.id, p_plan::public.subscription_plan, 'trialing', v_now, v_trial_end, v_now, v_trial_end
    )
    RETURNING * INTO v_subscription;

    INSERT INTO public.professional_trial_claims (user_id, workspace_id, claimed_at)
    VALUES (v_uid, v_workspace.id, v_now);

    v_trial_started := true;
  END IF;

  INSERT INTO public.workspace_members (workspace_id, user_id, role, status)
  VALUES (v_workspace.id, v_uid, 'owner', 'active');

  PERFORM set_config('app.bypass_protected_columns', 'off', true);

  RETURN jsonb_build_object(
    'workspace_id', v_workspace.id,
    'name', v_workspace.name,
    'slug', v_workspace.slug,
    'owner_user_id', v_workspace.owner_user_id,
    'subscription_id', v_subscription.id,
    'plan', v_subscription.plan,
    'status', v_subscription.status,
    'trial_started', v_trial_started,
    'trial_started_at', v_subscription.trial_started_at,
    'trial_ends_at', v_subscription.trial_ends_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION app.create_workspace_invite(p_workspace_id uuid, p_role member_role, p_email text DEFAULT NULL::text, p_ttl interval DEFAULT '7 days'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
  v_email text;
  v_token text;
  v_hash text;
  v_invite public.workspace_invites;
BEGIN
  v_uid := app.require_confirmed_email();

  IF NOT app.has_workspace_role(p_workspace_id, VARIADIC ARRAY['owner'::public.member_role, 'admin'::public.member_role]) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF p_role IS NULL OR p_role = 'owner' THEN
    RAISE EXCEPTION 'invalid_invite_role' USING ERRCODE = '22023';
  END IF;

  IF p_role IN ('admin', 'professional') THEN
    PERFORM app.assert_professional_seat_available(p_workspace_id);
  ELSE
    PERFORM app.lock_workspace_billing(p_workspace_id);
  END IF;

  v_email := CASE WHEN p_email IS NULL THEN NULL ELSE lower(btrim(p_email)) END;
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash := encode(extensions.digest(v_token, 'sha256'), 'hex');

  INSERT INTO public.workspace_invites (
    workspace_id, email, role, token_hash, expires_at, created_by
  ) VALUES (
    p_workspace_id, v_email, p_role, v_hash, clock_timestamp() + p_ttl, v_uid
  )
  RETURNING * INTO v_invite;

  RETURN jsonb_build_object(
    'invite_id', v_invite.id,
    'workspace_id', v_invite.workspace_id,
    'role', v_invite.role,
    'expires_at', v_invite.expires_at,
    'token', v_token
  );
END;
$function$

CREATE OR REPLACE FUNCTION app.deactivate_workspace_member(p_workspace_id uuid, p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_member public.workspace_members;
BEGIN
  PERFORM app.require_workspace_manager(p_workspace_id);
  PERFORM app.lock_workspace_membership(p_workspace_id);
  SELECT * INTO v_member FROM public.workspace_members m WHERE m.id = p_member_id FOR UPDATE;
  IF v_member.id IS NULL OR v_member.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'member_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM app.assert_member_change_allowed(
    p_workspace_id, v_member, v_member.role, 'inactive'::public.member_status
  );
  PERFORM set_config('app.bypass_protected_columns', 'on', true);
  UPDATE public.workspace_members SET status = 'inactive', updated_at = clock_timestamp() WHERE id = v_member.id;
  RETURN jsonb_build_object('member_id', v_member.id, 'status', 'inactive');
END;
$function$

CREATE OR REPLACE FUNCTION app.enforce_active_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_workspace_id uuid;
BEGIN
  v_workspace_id := COALESCE(NEW.workspace_id, OLD.workspace_id);
  PERFORM app.lock_workspace_membership(v_workspace_id);
  IF NOT EXISTS (
    SELECT 1 FROM public.workspace_members m
    WHERE m.workspace_id = v_workspace_id
      AND m.status = 'active'
      AND m.role = 'owner'::public.member_role
  ) THEN
    RAISE EXCEPTION 'last_owner_protected' USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.enforce_professional_seat_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_plan public.plans;
  v_seats integer;
  v_workspace_id uuid;
BEGIN
  v_workspace_id := COALESCE(NEW.workspace_id, OLD.workspace_id);

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  IF NEW.status = 'active' AND NEW.role IN ('owner', 'admin', 'professional') THEN
    PERFORM app.lock_workspace_billing(v_workspace_id);

    SELECT p.*
      INTO v_plan
    FROM public.subscriptions s
    JOIN public.plans p ON p.code = s.plan
    WHERE s.workspace_id = v_workspace_id;

    SELECT count(*)::integer
      INTO v_seats
    FROM public.workspace_members m
    WHERE m.workspace_id = v_workspace_id
      AND m.status = 'active'
      AND m.role IN ('owner', 'admin', 'professional');

    IF v_seats > v_plan.max_professionals THEN
      RAISE EXCEPTION 'plan_professional_limit_reached' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.enforce_workspace_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace_id uuid;
begin
  if current_setting('app.bypass_entitlement', true) = 'on' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  v_workspace_id := case
    when tg_op = 'DELETE' then old.workspace_id
    else new.workspace_id
  end;

  perform app.assert_workspace_entitled(v_workspace_id);

  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION app.expire_client_packages()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  perform set_config('app.bypass_entitlement','on',true);

  update public.client_packages
  set status='expired'::public.client_package_status
  where status='active'::public.client_package_status
    and expires_at is not null
    and expires_at <= now();

  get diagnostics v_count=row_count;

  perform set_config('app.bypass_entitlement','off',true);
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION app.expire_stale_trials()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  perform set_config('app.bypass_protected_columns','on',true);

  update public.subscriptions
  set status='expired'::public.subscription_status,
      current_period_end=coalesce(current_period_end,trial_ends_at),
      updated_at=now()
  where status='trialing'::public.subscription_status
    and trial_ends_at is not null
    and trial_ends_at <= now();

