CREATE OR REPLACE FUNCTION app.find_or_create_public_client(p_workspace_id uuid, p_full_name text, p_email text, p_phone text, p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_name text:=btrim(coalesce(p_full_name,''));
  v_email text:=nullif(lower(btrim(coalesce(p_email,''))),'');
  v_phone text;
begin
  if char_length(v_name)<2 or char_length(v_name)>120 then
    raise exception 'invalid_client_name' using errcode='22023';
  end if;

  if v_email is null or v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'invalid_email' using errcode='22023';
  end if;

  v_phone:=app.normalize_phone(p_phone);
  if v_phone is null then
    raise exception 'invalid_phone' using errcode='22023';
  end if;

  if p_user_id is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(p_workspace_id::text||'|user|'||p_user_id::text,0)
    );
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_workspace_id::text||'|phone|'||v_phone,0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended(p_workspace_id::text||'|email|'||v_email,0)
  );

  if p_user_id is not null then
    select c.id into v_id
    from public.workspace_clients c
    where c.workspace_id=p_workspace_id
      and c.linked_user_id=p_user_id
      and c.archived_at is null
    order by c.created_at
    limit 1;
  end if;

  if v_id is null then
    select c.id into v_id
    from public.workspace_clients c
    where c.workspace_id=p_workspace_id
      and c.archived_at is null
      and c.phone=v_phone
    order by c.created_at
    limit 1;
  end if;

  if v_id is null then
    select c.id into v_id
    from public.workspace_clients c
    where c.workspace_id=p_workspace_id
      and c.archived_at is null
      and c.email=v_email
    order by c.created_at
    limit 1;
  end if;

  if v_id is null then
    insert into public.workspace_clients(
      workspace_id,full_name,email,phone
    ) values(
      p_workspace_id,v_name,v_email,v_phone
    )
    returning id into v_id;
  else
    update public.workspace_clients
    set full_name=case
          when char_length(btrim(full_name))<2 then v_name
          else full_name
        end,
        email=coalesce(email,v_email),
        phone=coalesce(phone,v_phone)
    where id=v_id
      and workspace_id=p_workspace_id;
  end if;

  if p_user_id is not null then
    perform set_config('app.bypass_protected_columns','on',true);

    update public.workspace_clients
    set linked_user_id=p_user_id
    where id=v_id
      and workspace_id=p_workspace_id
      and linked_user_id is null;

    perform set_config('app.bypass_protected_columns','off',true);
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.get_finance_ui(p_workspace_id uuid, p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tz text;
  v_start timestamptz;
  v_end timestamptz;
begin
  perform app.assert_finance_manager(p_workspace_id);

  if p_start_date is null or p_end_date is null or p_end_date<p_start_date or p_end_date-p_start_date>366 then
    raise exception 'invalid_report_period' using errcode='22023';
  end if;

  v_tz:=app.workspace_timezone(p_workspace_id);
  v_start:=(p_start_date::timestamp at time zone v_tz);
  v_end:=((p_end_date+1)::timestamp at time zone v_tz);

  return jsonb_build_object(
    'report',app.get_workspace_advanced_report(p_workspace_id,p_start_date,p_end_date),
    'entries',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc)
      from (
        select
          f.id,f.entry_type,f.status,f.source,f.description,f.amount_cents,
          f.due_date,f.paid_at,f.payment_method,f.created_at,
          c.name as category_name,
          wc.full_name as client_name,
          coalesce((
            select sum(r.amount_cents)
            from public.financial_refunds r
            where r.financial_entry_id=f.id and r.workspace_id=f.workspace_id
          ),0)::bigint as refunded_cents
        from public.financial_entries f
        left join public.financial_categories c
          on c.id=f.category_id and c.workspace_id=f.workspace_id
        left join public.workspace_clients wc
          on wc.id=f.client_id and wc.workspace_id=f.workspace_id
        where f.workspace_id=p_workspace_id
          and f.created_at>=v_start and f.created_at<v_end
        order by f.created_at desc
        limit 100
      ) x
    ),'[]'::jsonb),
    'categories',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',c.id,'name',c.name,'entry_type',c.entry_type,
          'system_key',c.system_key,'active',c.active,'archived_at',c.archived_at
        )
        order by c.entry_type,c.name
      )
      from public.financial_categories c
      where c.workspace_id=p_workspace_id
    ),'[]'::jsonb)
  );
end;
$function$

