CREATE OR REPLACE FUNCTION app.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_full_name text;
  v_phone text;
  v_intended public.signup_intent;
  v_terms timestamptz;
  v_privacy timestamptz;
BEGIN
  v_full_name := nullif(btrim(COALESCE(NEW.raw_user_meta_data->>'full_name', '')), '');
  v_phone := app.normalize_phone(COALESCE(NEW.raw_user_meta_data->>'phone', ''));

  IF NEW.raw_user_meta_data->>'intended_use' = 'professional' THEN
    v_intended := 'professional';
  ELSE
    v_intended := 'client';
  END IF;

  IF COALESCE((NEW.raw_user_meta_data->>'terms_accepted')::boolean, false) THEN
    v_terms := COALESCE(NEW.created_at, now());
  END IF;
  IF COALESCE((NEW.raw_user_meta_data->>'privacy_accepted')::boolean, false) THEN
    v_privacy := COALESCE(NEW.created_at, now());
  END IF;

  INSERT INTO public.profiles (
    user_id,
    full_name,
    email,
    phone,
    intended_use,
    terms_accepted_at,
    privacy_accepted_at
  ) VALUES (
    NEW.id,
    COALESCE(v_full_name, 'Usuário'),
    lower(btrim(NEW.email)),
    v_phone,
    v_intended,
    v_terms,
    v_privacy
  );

  IF v_intended = 'client' THEN
    INSERT INTO public.client_profiles (user_id)
    VALUES (NEW.id)
    ON CONFLICT (user_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.link_workspace_clients_by_confirmed_email()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
  v_email text;
  v_count integer := 0;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN 0;
  END IF;
  IF NOT COALESCE((auth.jwt() ->> 'email_verified')::boolean, false)
     AND NOT EXISTS (
       SELECT 1 FROM auth.users u
       WHERE u.id = v_uid AND u.email_confirmed_at IS NOT NULL
     ) THEN
    RETURN 0;
  END IF;

  SELECT lower(u.email) INTO v_email
  FROM auth.users u
  WHERE u.id = v_uid;
  IF v_email IS NULL THEN
    RETURN 0;
  END IF;

  PERFORM set_config('app.bypass_protected_columns', 'on', true);
  UPDATE public.workspace_clients c
  SET linked_user_id = v_uid
  WHERE c.linked_user_id IS NULL
    AND c.archived_at IS NULL
    AND c.email = v_email;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  PERFORM set_config('app.bypass_protected_columns', 'off', true);
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION app.list_public_available_slots(p_slug text, p_service_id uuid, p_professional_member_id uuid, p_local_date date)
 RETURNS TABLE(starts_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_ws uuid;
  v_tz text;
  v_today date;
  v_lead timestamptz;
BEGIN
  v_ws := app.resolve_public_workspace(p_slug);
  v_tz := app.workspace_timezone(v_ws);
  v_today := (clock_timestamp() AT TIME ZONE v_tz)::date;
  v_lead := clock_timestamp() + make_interval(mins => app.booking_min_lead_minutes());

  IF NOT EXISTS (
    SELECT 1
    FROM public.services s
    WHERE s.id = p_service_id
      AND s.workspace_id = v_ws
      AND s.active
      AND s.archived_at IS NULL
  ) THEN
    RETURN;
  END IF;

  IF p_local_date IS NULL OR p_local_date < v_today THEN
    RETURN;
  END IF;
  IF p_local_date > v_today + app.booking_horizon_days() THEN
    RETURN;
  END IF;

  IF p_professional_member_id IS NOT NULL THEN
    RETURN QUERY
    SELECT s.starts_at
    FROM app.compute_available_slots(v_ws, p_professional_member_id, p_service_id, p_local_date) s
    WHERE s.starts_at >= v_lead;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT DISTINCT s.starts_at
  FROM public.professional_profiles p
  JOIN public.workspace_members m
    ON m.id = p.member_id AND m.workspace_id = p.workspace_id
  JOIN public.professional_services ps
    ON ps.professional_member_id = p.member_id
   AND ps.workspace_id = p.workspace_id
   AND ps.service_id = p_service_id
   AND ps.active
  JOIN LATERAL app.compute_available_slots(v_ws, p.member_id, p_service_id, p_local_date) s ON true
  WHERE p.workspace_id = v_ws
    AND p.booking_enabled
    AND m.status = 'active'
    AND s.starts_at >= v_lead
  ORDER BY 1;
END;
$function$

