CREATE OR REPLACE FUNCTION app.lock_professional_pair(p_a uuid, p_b uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_a is null or p_b is null then
    raise exception 'invalid_professional_lock' using errcode='22023';
  end if;

  if p_a=p_b then
    perform app.lock_professional_agenda(p_a);
  elsif p_a::text < p_b::text then
    perform app.lock_professional_agenda(p_a);
