CREATE OR REPLACE FUNCTION app.mark_financial_entry_paid(p_workspace_id uuid, p_entry_id uuid, p_payment_method payment_method, p_paid_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_entry public.financial_entries%rowtype;
begin
  perform app.assert_finance_operator(p_workspace_id);
  select * into v_entry from public.financial_entries
  where id=p_entry_id and workspace_id=p_workspace_id for update;
  if v_entry.id is null then raise exception 'financial_entry_not_found' using errcode='P0002'; end if;
  if v_entry.status <> 'pending' then raise exception 'financial_entry_not_pending' using errcode='22023'; end if;
  if v_entry.entry_type='expense' and not app.has_workspace_role(
    p_workspace_id,
    variadic array['owner'::public.member_role,'admin'::public.member_role]
  ) then raise exception 'not_authorized' using errcode='42501'; end if;
  if p_payment_method is null then raise exception 'payment_method_required' using errcode='22023'; end if;
  update public.financial_entries
  set status='paid',paid_at=coalesce(p_paid_at,now()),payment_method=p_payment_method,cancelled_at=null
  where id=v_entry.id and workspace_id=p_workspace_id;
  return v_entry.id;
end;
$function$

CREATE OR REPLACE FUNCTION app.normalize_inventory_quantity(p_value numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE v_qty numeric(12, 3);
BEGIN
  IF p_value IS NULL THEN
    RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
  END IF;
  v_qty := round(p_value, 3);
  IF v_qty < 0 OR v_qty > 999999999.999 THEN
    RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
  END IF;
  RETURN v_qty;
END;
$function$

CREATE OR REPLACE FUNCTION app.normalize_phone(input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  digits text;
  national text;
BEGIN
  digits := regexp_replace(coalesce(input, ''), '\D', '', 'g');
  IF digits = '' THEN
    RETURN NULL;
  END IF;

  -- Country code 55 only when the remainder is a valid 10/11-digit national number.
  -- This keeps DDD 55 (e.g. (55) 99999-9999) instead of treating it as +55.
  IF left(digits, 2) = '55' AND length(digits) >= 12 THEN
    national := substr(digits, 3);
    IF app.is_valid_br_national(national) THEN
      RETURN '+55' || national;
    END IF;
  END IF;

  IF app.is_valid_br_national(digits) THEN
    RETURN '+55' || digits;
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION app.peek_workspace_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hash text;
  v_invite public.workspace_invites;
  v_name text;
  v_status text;
BEGIN
  IF p_token IS NULL OR char_length(p_token) < 16 THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  v_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');

  SELECT * INTO v_invite
  FROM public.workspace_invites i
  WHERE i.token_hash = v_hash;

  IF v_invite.id IS NULL THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  SELECT w.name INTO v_name
  FROM public.workspaces w
  WHERE w.id = v_invite.workspace_id;

  IF v_invite.revoked_at IS NOT NULL THEN
    v_status := 'revoked';
  ELSIF v_invite.accepted_at IS NOT NULL THEN
    v_status := 'accepted';
  ELSIF v_invite.expires_at <= clock_timestamp() THEN
    v_status := 'expired';
  ELSE
    v_status := 'valid';
  END IF;

  RETURN jsonb_build_object(
    'status', v_status,
    'workspace_name', v_name,
    'role', v_invite.role,
    'email_bound', v_invite.email IS NOT NULL,
    'expires_at', v_invite.expires_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION app.protect_appointment_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := COALESCE(NEW.created_by, auth.uid());
    NEW.notes := nullif(btrim(COALESCE(NEW.notes, '')), '');
    NEW.customer_note := nullif(btrim(COALESCE(NEW.customer_note, '')), '');
    RETURN NEW;
  END IF;
  IF current_setting('app.bypass_protected_columns', true) = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'appointment_identity_immutable' USING ERRCODE = '42501';
  END IF;
  IF current_setting('app.allow_appointment_snapshot', true) IS DISTINCT FROM 'on' THEN
    IF NEW.price_cents IS DISTINCT FROM OLD.price_cents
       OR NEW.duration_minutes IS DISTINCT FROM OLD.duration_minutes THEN
      RAISE EXCEPTION 'appointment_snapshot_immutable' USING ERRCODE = '42501';
    END IF;
  END IF;
  NEW.notes := nullif(btrim(COALESCE(NEW.notes, '')), '');
  NEW.customer_note := nullif(btrim(COALESCE(NEW.customer_note, '')), '');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.protect_break_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.label := nullif(btrim(COALESCE(NEW.label, '')), '');
    RETURN NEW;
  END IF;
  IF current_setting('app.bypass_protected_columns', true) = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
     OR NEW.professional_member_id IS DISTINCT FROM OLD.professional_member_id THEN
    RAISE EXCEPTION 'break_identity_immutable' USING ERRCODE = '42501';
  END IF;
  NEW.label := nullif(btrim(COALESCE(NEW.label, '')), '');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.protect_inventory_product_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN
      RAISE EXCEPTION 'inventory_product_identity_immutable' USING ERRCODE = '42501';
    END IF;
    IF NEW.quantity IS DISTINCT FROM OLD.quantity AND current_setting('app.inventory_mutating', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'inventory_quantity_direct_update_denied' USING ERRCODE = '42501';
    END IF;
  END IF;
  NEW.name := btrim(NEW.name);
  NEW.description := nullif(btrim(COALESCE(NEW.description, '')), '');
  NEW.sku := nullif(btrim(COALESCE(NEW.sku, '')), '');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.protect_membership_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF current_setting('app.bypass_protected_columns', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
