end;
$function$

CREATE OR REPLACE FUNCTION app.replace_service_package_items(p_workspace_id uuid, p_package_id uuid, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_item jsonb; v_service_id uuid; v_quantity integer;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items)=0 then
    raise exception 'invalid_package_items' using errcode='22023';
  end if;
  delete from public.service_package_items where workspace_id=p_workspace_id and package_id=p_package_id;
  for v_item in select value from jsonb_array_elements(p_items)
  loop
    begin
      v_service_id := (v_item->>'service_id')::uuid;
      v_quantity := (v_item->>'quantity')::integer;
    exception when others then
      raise exception 'invalid_package_item' using errcode='22023';
    end;
    if v_quantity is null or v_quantity < 1 or v_quantity > 100 then
      raise exception 'invalid_package_quantity' using errcode='22023';
    end if;
    if not exists (
      select 1 from public.services s
      where s.id=v_service_id and s.workspace_id=p_workspace_id and s.archived_at is null and s.active
    ) then raise exception 'service_not_found' using errcode='22023'; end if;
    insert into public.service_package_items(workspace_id,package_id,service_id,quantity)
    values(p_workspace_id,p_package_id,v_service_id,v_quantity)
    on conflict (package_id,service_id) do update set quantity=excluded.quantity;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION app.require_authenticated_user()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated'
      USING ERRCODE = '42501';
  END IF;
  RETURN v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION app.require_confirmed_email()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid;
  v_confirmed timestamptz;
BEGIN
  v_uid := app.require_authenticated_user();
  SELECT u.email_confirmed_at
    INTO v_confirmed
  FROM auth.users u
  WHERE u.id = v_uid;

  IF v_confirmed IS NULL THEN
    RAISE EXCEPTION 'email_not_confirmed'
      USING ERRCODE = '42501';
  END IF;

  RETURN v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION app.require_workspace_manager(p_workspace_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
begin
  v_uid := app.require_confirmed_email();
  perform app.assert_workspace_entitled(p_workspace_id);

  if not app.has_workspace_role(
    p_workspace_id,
    variadic array['owner'::public.member_role, 'admin'::public.member_role]
  ) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  return v_uid;
end;
$function$

CREATE OR REPLACE FUNCTION app.reschedule_appointment(p_appointment_id uuid, p_professional_member_id uuid, p_service_id uuid, p_starts_at timestamp with time zone, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.appointments%rowtype;
  v_snapshot record;
  v_ends timestamptz;
  v_price integer;
  v_duration integer;
  v_notes text;
begin
  perform app.require_confirmed_email();

  select a.* into v_row
  from public.appointments a
  where a.id=p_appointment_id
  for update;

  if v_row.id is null then
    raise exception 'appointment_not_found' using errcode='22023';
  end if;

  perform app.assert_workspace_entitled(v_row.workspace_id);

  if not app.can_write_appointment(v_row.workspace_id,v_row.professional_member_id)
     or not app.can_write_appointment(v_row.workspace_id,p_professional_member_id) then
    raise exception 'appointment_write_denied' using errcode='42501';
  end if;

  if v_row.status in (
    'completed'::public.appointment_status,
    'cancelled'::public.appointment_status,
    'no_show'::public.appointment_status
  ) then
    raise exception 'appointment_terminal' using errcode='22023';
  end if;

  if v_row.status='in_progress'::public.appointment_status then
    raise exception 'appointment_in_progress' using errcode='22023';
  end if;

  perform app.lock_professional_pair(
    v_row.professional_member_id,
    p_professional_member_id
  );

  if p_service_id is distinct from v_row.service_id
     or p_professional_member_id is distinct from v_row.professional_member_id then
    select s.price_cents,s.duration_minutes
    into v_snapshot
    from app.resolve_service_snapshot(
      v_row.workspace_id,p_professional_member_id,p_service_id
    ) s;

    v_price:=v_snapshot.price_cents;
    v_duration:=v_snapshot.duration_minutes;
  else
    perform 1
    from app.resolve_service_snapshot(
      v_row.workspace_id,p_professional_member_id,p_service_id
    );

    v_price:=v_row.price_cents;
    v_duration:=v_row.duration_minutes;
  end if;

  v_ends:=p_starts_at+make_interval(mins=>v_duration);
  v_notes:=case
    when p_notes is null then v_row.notes
    else nullif(btrim(p_notes),'')
  end;

  perform app.assert_slot_available(
    v_row.workspace_id,
    p_professional_member_id,
    p_starts_at,
    v_ends,
    v_row.id
  );

  perform set_config('app.allow_appointment_snapshot','on',true);

  update public.appointments
  set professional_member_id=p_professional_member_id,
      service_id=p_service_id,
      starts_at=p_starts_at,
      ends_at=v_ends,
      price_cents=v_price,
      duration_minutes=v_duration,
      notes=v_notes
  where id=v_row.id
    and workspace_id=v_row.workspace_id;

  perform set_config('app.allow_appointment_snapshot','off',true);

  return v_row.id;
end;
$function$

CREATE OR REPLACE FUNCTION app.reschedule_my_appointment(p_appointment_id uuid, p_starts_at timestamp with time zone, p_professional_member_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_row public.appointments%rowtype;
  v_target_professional uuid;
  v_ends timestamptz;
  v_workspace_name text;
  v_slug text;
  v_service_name text;
  v_professional_name text;
  v_timezone text;
begin
  v_uid:=app.require_confirmed_email();
  perform app.link_workspace_clients_by_confirmed_email();

  select a.* into v_row
  from public.appointments a
  join public.workspace_clients c
    on c.id=a.client_id
   and c.workspace_id=a.workspace_id
  where a.id=p_appointment_id
    and c.linked_user_id=v_uid
  for update of a;

  if v_row.id is null then
    raise exception 'appointment_not_found' using errcode='42501';
  end if;

  perform app.assert_workspace_entitled(v_row.workspace_id);

  if v_row.status not in (
    'scheduled'::public.appointment_status,
    'confirmed'::public.appointment_status
  ) then
    raise exception 'appointment_not_reschedulable' using errcode='22023';
  end if;

  if v_row.starts_at <
     clock_timestamp()+make_interval(mins=>app.client_cancel_lead_minutes()) then
    raise exception 'reschedule_too_late' using errcode='22023';
  end if;

  perform app.assert_public_booking_window(v_row.workspace_id,p_starts_at);

  v_target_professional:=coalesce(
    p_professional_member_id,
    v_row.professional_member_id
  );

  perform 1
  from app.resolve_service_snapshot(
    v_row.workspace_id,
    v_target_professional,
    v_row.service_id
  );

  perform app.lock_professional_pair(
    v_row.professional_member_id,
    v_target_professional
  );

  v_ends:=p_starts_at+make_interval(mins=>v_row.duration_minutes);

  perform app.assert_slot_available(
    v_row.workspace_id,
    v_target_professional,
    p_starts_at,
    v_ends,
    v_row.id
  );

  perform set_config('app.allow_appointment_snapshot','on',true);

  update public.appointments
  set professional_member_id=v_target_professional,
      starts_at=p_starts_at,
      ends_at=v_ends
  where id=v_row.id
    and workspace_id=v_row.workspace_id;

  perform set_config('app.allow_appointment_snapshot','off',true);

  select w.name,w.slug,app.workspace_timezone(w.id)
  into v_workspace_name,v_slug,v_timezone
  from public.workspaces w
  where w.id=v_row.workspace_id;

  select s.name into v_service_name
  from public.services s
  where s.id=v_row.service_id
    and s.workspace_id=v_row.workspace_id;

  select p.display_name into v_professional_name
  from public.professional_profiles p
  where p.member_id=v_target_professional
    and p.workspace_id=v_row.workspace_id;

  return jsonb_build_object(
    'id',v_row.id,
    'workspace_name',v_workspace_name,
    'slug',v_slug,
    'service_name',v_service_name,
    'professional_name',v_professional_name,
    'starts_at',p_starts_at,
    'ends_at',v_ends,
    'duration_minutes',v_row.duration_minutes,
    'price_cents',v_row.price_cents,
    'status',v_row.status,
    'timezone',v_timezone
  );
end;
$function$

CREATE OR REPLACE FUNCTION app.resolve_public_workspace(p_slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_slug text := lower(btrim(coalesce(p_slug, '')));
begin
  if v_slug = '' then
    raise exception 'workspace_not_found' using errcode = '22023';
  end if;

  select w.id into v_id
  from public.workspaces w
  where w.slug = v_slug;

  if v_id is null then
    raise exception 'workspace_not_found' using errcode = '22023';
  end if;

  if not app.workspace_has_entitlement(v_id) then
    raise exception 'workspace_unavailable' using errcode = '22023';
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.resolve_service_snapshot(p_workspace_id uuid, p_professional_member_id uuid, p_service_id uuid)
 RETURNS TABLE(price_cents integer, duration_minutes integer)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_service public.services%ROWTYPE;
  v_link public.professional_services%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.professional_profiles p
    WHERE p.member_id = p_professional_member_id
      AND p.workspace_id = p_workspace_id
  ) THEN
    RAISE EXCEPTION 'professional_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT s.* INTO v_service
  FROM public.services s
  WHERE s.id = p_service_id
    AND s.workspace_id = p_workspace_id;

  IF v_service.id IS NULL THEN
    RAISE EXCEPTION 'service_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_service.archived_at IS NOT NULL OR v_service.active IS NOT TRUE THEN
    RAISE EXCEPTION 'service_inactive' USING ERRCODE = '22023';
  END IF;

  SELECT ps.* INTO v_link
  FROM public.professional_services ps
  WHERE ps.workspace_id = p_workspace_id
    AND ps.professional_member_id = p_professional_member_id
    AND ps.service_id = p_service_id
    AND ps.active;

  IF v_link.id IS NULL THEN
    RAISE EXCEPTION 'professional_service_inactive' USING ERRCODE = '22023';
  END IF;

  price_cents := COALESCE(v_link.price_override_cents, v_service.price_cents);
  duration_minutes := COALESCE(v_link.duration_override_minutes, v_service.duration_minutes);
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION app.reverse_package_redemption(p_workspace_id uuid, p_redemption_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_r public.package_redemptions%rowtype;
  v_item public.client_package_items%rowtype;
  v_cp public.client_packages%rowtype;
  v_appt public.appointments%rowtype;
  v_fin public.financial_entries%rowtype;
  v_new_status public.client_package_status;
begin
  perform app.assert_package_manager(p_workspace_id);

  if char_length(btrim(coalesce(p_reason,''))) < 3 then
    raise exception 'reversal_reason_required' using errcode='22023';
  end if;

  select * into v_r
  from public.package_redemptions
  where id=p_redemption_id
    and workspace_id=p_workspace_id
  for update;

  if v_r.id is null then
    raise exception 'package_redemption_not_found' using errcode='P0002';
  end if;

  if v_r.reversed_at is not null then
    raise exception 'package_redemption_already_reversed' using errcode='22023';
  end if;

  select * into v_item
  from public.client_package_items
  where id=v_r.client_package_item_id
    and workspace_id=p_workspace_id
  for update;

  select * into v_cp
  from public.client_packages
  where id=v_r.client_package_id
    and workspace_id=p_workspace_id
  for update;

  select * into v_appt
  from public.appointments
  where id=v_r.appointment_id
    and workspace_id=p_workspace_id
  for share;

  if v_item.id is null or v_cp.id is null or v_appt.id is null then
    raise exception 'package_redemption_integrity_error' using errcode='22023';
  end if;

  if v_item.used_quantity <= 0 then
    raise exception 'package_item_usage_invalid' using errcode='22023';
  end if;

  update public.client_package_items
  set used_quantity=used_quantity-1
  where id=v_item.id
    and workspace_id=p_workspace_id;

  if v_cp.status='cancelled'::public.client_package_status then
    v_new_status := 'cancelled'::public.client_package_status;
  elsif v_cp.expires_at is not null and v_cp.expires_at <= now() then
    v_new_status := 'expired'::public.client_package_status;
  else
    v_new_status := 'active'::public.client_package_status;
  end if;

  update public.client_packages
  set status=v_new_status
  where id=v_cp.id
    and workspace_id=p_workspace_id;

  perform set_config('app.package_redemption_mutating','on',true);
  update public.package_redemptions
  set reversed_at=now(),
      reversed_by=auth.uid(),
      reversal_reason=btrim(p_reason)
  where id=v_r.id
    and workspace_id=p_workspace_id;
  perform set_config('app.package_redemption_mutating','off',true);

  select * into v_fin
  from public.financial_entries
  where appointment_id=v_appt.id
    and workspace_id=p_workspace_id
    and source='appointment'::public.financial_entry_source
  for update;

  if v_fin.id is null then
    insert into public.financial_entries(
      workspace_id,entry_type,status,source,description,amount_cents,
      appointment_id,client_id,created_by
    ) values(
      p_workspace_id,
      'income'::public.financial_entry_type,
      'pending'::public.financial_entry_status,
      'appointment'::public.financial_entry_source,
      'Atendimento concluído',
      v_appt.price_cents,
      v_appt.id,
      v_appt.client_id,
      auth.uid()
    );
  elsif v_fin.status='cancelled'::public.financial_entry_status then
    update public.financial_entries
    set status='pending'::public.financial_entry_status,
        cancelled_at=null,
        paid_at=null,
        payment_method=null
    where id=v_fin.id
      and workspace_id=p_workspace_id;
  end if;

  return jsonb_build_object(
    'redemption_id',v_r.id,
    'client_package_id',v_cp.id,
    'appointment_id',v_appt.id,
    'package_status',v_new_status,
    'remaining_after_reversal',
      v_item.included_quantity-(v_item.used_quantity-1)
  );
end;
$function$

CREATE OR REPLACE FUNCTION app.revoke_workspace_invite(p_workspace_id uuid, p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_invite public.workspace_invites;
BEGIN
  PERFORM app.require_workspace_manager(p_workspace_id);

  SELECT * INTO v_invite
  FROM public.workspace_invites i
  WHERE i.id = p_invite_id
  FOR UPDATE;

  IF v_invite.id IS NULL OR v_invite.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'invite_not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.workspace_invites
  SET revoked_at = clock_timestamp(),
      updated_at = clock_timestamp()
  WHERE id = v_invite.id
    AND revoked_at IS NULL
    AND accepted_at IS NULL;

  RETURN jsonb_build_object('invite_id', v_invite.id, 'revoked', true);
END;
$function$

CREATE OR REPLACE FUNCTION app.sell_service_package(p_workspace_id uuid, p_client_id uuid, p_package_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_package public.service_packages%rowtype; v_client_archived timestamptz; v_id uuid;
begin
  perform app.assert_package_operator(p_workspace_id);
  select * into v_package from public.service_packages
  where id=p_package_id and workspace_id=p_workspace_id for share;
  if v_package.id is null or v_package.archived_at is not null or not v_package.active then
    raise exception 'package_not_available' using errcode='22023';
  end if;
  select archived_at into v_client_archived from public.workspace_clients
  where id=p_client_id and workspace_id=p_workspace_id;
  if not found then raise exception 'client_not_found' using errcode='22023'; end if;
  if v_client_archived is not null then raise exception 'client_archived' using errcode='22023'; end if;
  if not exists(select 1 from public.service_package_items where package_id=p_package_id and workspace_id=p_workspace_id) then
    raise exception 'package_has_no_items' using errcode='22023';
  end if;
  insert into public.client_packages(
    workspace_id,client_id,package_id,package_name_snapshot,price_cents,expires_at,status,created_by
  ) values(
    p_workspace_id,p_client_id,p_package_id,v_package.name,v_package.price_cents,
    case when v_package.validity_days is null then null else now()+make_interval(days=>v_package.validity_days) end,
    'active',auth.uid()
  ) returning id into v_id;
  insert into public.client_package_items(workspace_id,client_package_id,service_id,included_quantity,used_quantity)
  select workspace_id,v_id,service_id,quantity,0 from public.service_package_items
  where workspace_id=p_workspace_id and package_id=p_package_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.set_appointment_status(p_appointment_id uuid, p_status appointment_status)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_row public.appointments%ROWTYPE;
  v_actor public.workspace_members;
BEGIN
  PERFORM app.require_confirmed_email();

  SELECT a.* INTO v_row
  FROM public.appointments a
  WHERE a.id = p_appointment_id;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'appointment_not_found' USING ERRCODE = '22023';
  END IF;

  v_actor := app.actor_member(v_row.workspace_id);

  IF NOT app.can_write_appointment(v_row.workspace_id, v_row.professional_member_id) THEN
    RAISE EXCEPTION 'appointment_write_denied' USING ERRCODE = '42501';
  END IF;

  PERFORM app.assert_status_transition(v_row.status, p_status, v_actor.role);

  UPDATE public.appointments
  SET status = p_status
  WHERE id = v_row.id
    AND workspace_id = v_row.workspace_id;

  RETURN v_row.id;
END;
$function$

CREATE OR REPLACE FUNCTION app.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.sync_billing_subscription(p_workspace_id uuid, p_provider text, p_external_customer_id text, p_external_subscription_id text, p_plan subscription_plan, p_billing_interval billing_interval, p_status subscription_status, p_current_period_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_current_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_canceled_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_subscription public.subscriptions%rowtype;
  v_provider text := lower(btrim(coalesce(p_provider, '')));
  v_customer_id text := btrim(coalesce(p_external_customer_id, ''));
  v_subscription_id text := btrim(coalesce(p_external_subscription_id, ''));
  v_canceled_at timestamptz;
  v_max_professionals integer;
  v_used_professionals integer;
begin
  if p_workspace_id is null then
    raise exception 'workspace_required' using errcode = '22023';
  end if;

  if v_provider <> 'stripe' then
    raise exception 'billing_provider_invalid' using errcode = '22023';
  end if;

  if v_customer_id = '' or char_length(v_customer_id) > 200 then
    raise exception 'external_customer_invalid' using errcode = '22023';
  end if;

  if v_subscription_id = '' or char_length(v_subscription_id) > 200 then
    raise exception 'external_subscription_invalid' using errcode = '22023';
  end if;

  if p_plan is null or p_billing_interval is null or p_status is null then
    raise exception 'billing_state_required' using errcode = '22023';
  end if;

  if p_current_period_start is not null
     and p_current_period_end is not null
     and p_current_period_end <= p_current_period_start then
    raise exception 'billing_period_invalid' using errcode = '22023';
  end if;

  if p_status in (
       'active'::public.subscription_status,
       'past_due'::public.subscription_status
     )
     and (p_current_period_start is null or p_current_period_end is null) then
    raise exception 'billing_period_required' using errcode = '22023';
  end if;

  select p.max_professionals
    into v_max_professionals
  from public.plans p
  where p.code = p_plan;

  if v_max_professionals is null then
    raise exception 'plan_not_found' using errcode = '22023';
  end if;

  v_used_professionals := app.workspace_professional_seats(p_workspace_id);
  if v_used_professionals > v_max_professionals then
    raise exception 'plan_seat_limit_exceeded' using errcode = '23514';
  end if;

  select *
    into v_subscription
  from public.subscriptions
  where workspace_id = p_workspace_id
  for update;

  if not found then
    raise exception 'subscription_missing' using errcode = 'P0001';
  end if;

  if v_subscription.billing_provider is not null
     and v_subscription.billing_provider <> v_provider then
    raise exception 'billing_provider_conflict' using errcode = 'P0001';
  end if;

  if v_subscription.external_customer_id is not null
     and v_subscription.external_customer_id <> v_customer_id then
    raise exception 'external_customer_conflict' using errcode = 'P0001';
  end if;

  if v_subscription.external_subscription_id is not null
     and v_subscription.external_subscription_id <> v_subscription_id
     and v_subscription.status not in (
       'canceled'::public.subscription_status,
       'expired'::public.subscription_status
     ) then
    raise exception 'external_subscription_conflict' using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from public.subscriptions s
    where s.workspace_id <> p_workspace_id
      and s.billing_provider = v_provider
      and (
        s.external_customer_id = v_customer_id
        or s.external_subscription_id = v_subscription_id
      )
  ) then
    raise exception 'external_billing_identity_already_bound' using errcode = '23505';
  end if;

  v_canceled_at :=
    case
      when p_status = 'canceled'::public.subscription_status
        then coalesce(p_canceled_at, now())
      else null
    end;

  perform set_config('app.bypass_protected_columns', 'on', true);

  update public.subscriptions
  set plan = p_plan,
      status = p_status,
      billing_interval = p_billing_interval,
      billing_provider = v_provider,
      external_customer_id = v_customer_id,
      external_subscription_id = v_subscription_id,
      current_period_start = p_current_period_start,
      current_period_end = p_current_period_end,
      canceled_at = v_canceled_at
  where workspace_id = p_workspace_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.sync_professional_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_name text;
  v_qualifies boolean;
  v_was_qualified boolean := false;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  v_qualifies := NEW.status = 'active'
    AND NEW.role IN ('owner'::public.member_role, 'admin'::public.member_role, 'professional'::public.member_role);

  IF TG_OP = 'UPDATE' THEN
    v_was_qualified := OLD.status = 'active'
      AND OLD.role IN ('owner'::public.member_role, 'admin'::public.member_role, 'professional'::public.member_role);
  END IF;

  IF v_qualifies THEN
    SELECT p.full_name INTO v_name
    FROM public.profiles p
    WHERE p.user_id = NEW.user_id;

    INSERT INTO public.professional_profiles (member_id, workspace_id, display_name, booking_enabled)
    VALUES (
      NEW.id,
      NEW.workspace_id,
      COALESCE(nullif(btrim(v_name), ''), 'Profissional'),
      true
    )
    ON CONFLICT (member_id) DO NOTHING;

    IF TG_OP = 'UPDATE' AND NOT v_was_qualified THEN
      UPDATE public.professional_profiles
      SET booking_enabled = true,
          updated_at = now()
      WHERE member_id = NEW.id;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_was_qualified THEN
    UPDATE public.professional_profiles
    SET booking_enabled = false,
        updated_at = now()
    WHERE member_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$function$

