CREATE OR REPLACE FUNCTION app.update_financial_category(p_workspace_id uuid, p_category_id uuid, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app.assert_finance_manager(p_workspace_id);

  update public.financial_categories
  set name=btrim(p_name)
  where id=p_category_id
    and workspace_id=p_workspace_id
    and archived_at is null;

  if not found then
    raise exception 'financial_category_not_found' using errcode='P0002';
  end if;

  return p_category_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.update_financial_entry(p_workspace_id uuid, p_entry_id uuid, p_description text, p_amount_cents integer, p_due_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app.assert_finance_manager(p_workspace_id);
  if p_amount_cents is null or p_amount_cents <= 0 or p_amount_cents > 1000000000 then
    raise exception 'invalid_amount' using errcode='22023';
  end if;
  update public.financial_entries
  set description=btrim(p_description), amount_cents=p_amount_cents, due_date=p_due_date
  where id=p_entry_id and workspace_id=p_workspace_id and source='manual' and status='pending';
  if not found then raise exception 'financial_entry_not_editable' using errcode='22023'; end if;
  return p_entry_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.update_inventory_product(p_workspace_id uuid, p_product_id uuid, p_name text, p_description text DEFAULT NULL::text, p_sku text DEFAULT NULL::text, p_unit inventory_unit DEFAULT 'unidade'::inventory_unit, p_minimum_quantity numeric DEFAULT 0, p_cost_cents integer DEFAULT NULL::integer, p_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_product public.inventory_products;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
  END IF;
  PERFORM app.assert_inventory_manager(p_workspace_id);
  PERFORM app.lock_inventory_product(p_workspace_id, p_product_id);
  UPDATE public.inventory_products SET
    name = btrim(p_name),
    description = nullif(btrim(COALESCE(p_description, '')), ''),
    sku = nullif(btrim(COALESCE(p_sku, '')), ''),
    unit = p_unit,
    minimum_quantity = app.normalize_inventory_quantity(COALESCE(p_minimum_quantity, 0)),
    cost_cents = p_cost_cents,
    active = CASE WHEN archived_at IS NULL THEN p_active ELSE false END
  WHERE id = p_product_id AND workspace_id = p_workspace_id
  RETURNING * INTO v_product;
  RETURN jsonb_build_object('id', v_product.id, 'name', v_product.name, 'quantity', v_product.quantity, 'active', v_product.active);
END;
$function$

CREATE OR REPLACE FUNCTION app.update_service_package(p_workspace_id uuid, p_package_id uuid, p_name text, p_description text, p_price_cents integer, p_validity_days integer, p_active boolean, p_items jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform app.assert_package_manager(p_workspace_id);
  if p_price_cents is null or p_price_cents < 0 or p_price_cents > 100000000 then
    raise exception 'invalid_package_price' using errcode='22023';
  end if;
  update public.service_packages
  set name=btrim(p_name),description=nullif(btrim(coalesce(p_description,'')),''),
      price_cents=p_price_cents,validity_days=p_validity_days,
      active=case when archived_at is null then coalesce(p_active,true) else false end
  where id=p_package_id and workspace_id=p_workspace_id;
  if not found then raise exception 'package_not_found' using errcode='P0002'; end if;
  perform app.replace_service_package_items(p_workspace_id,p_package_id,p_items);
  return p_package_id;
end;
$function$

CREATE OR REPLACE FUNCTION app.update_workspace_member_role(p_workspace_id uuid, p_member_id uuid, p_role member_role)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_member public.workspace_members;
  v_needs_seat boolean;
BEGIN
  PERFORM app.require_workspace_manager(p_workspace_id);
  PERFORM app.lock_workspace_membership(p_workspace_id);
  IF p_role IS NULL OR p_role = 'owner'::public.member_role THEN
    RAISE EXCEPTION 'owner_transfer_not_supported' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_member FROM public.workspace_members m WHERE m.id = p_member_id FOR UPDATE;
  IF v_member.id IS NULL OR v_member.workspace_id IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'member_not_found' USING ERRCODE = 'P0002';
  END IF;
  PERFORM app.assert_member_change_allowed(p_workspace_id, v_member, p_role, v_member.status);
  v_needs_seat := p_role IN ('admin'::public.member_role, 'professional'::public.member_role)
    AND v_member.status = 'active'::public.member_status
    AND v_member.role = 'receptionist'::public.member_role;
  IF v_needs_seat THEN
    PERFORM app.assert_professional_seat_available(p_workspace_id);
  END IF;
  PERFORM set_config('app.bypass_protected_columns', 'on', true);
  UPDATE public.workspace_members SET role = p_role, updated_at = clock_timestamp() WHERE id = v_member.id;
  RETURN jsonb_build_object('member_id', v_member.id, 'role', p_role);
END;
$function$

CREATE OR REPLACE FUNCTION app.update_workspace_settings(p_workspace_id uuid, p_name text, p_slug text, p_business_phone text, p_business_email text, p_description text, p_address text, p_city text, p_state text, p_postal_code text, p_instagram text, p_timezone text, p_logo_path text DEFAULT NULL::text, p_clear_logo boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_name text;
  v_slug text;
  v_phone text;
  v_email text;
  v_instagram text;
  v_postal text;
  v_state text;
  v_workspace public.workspaces;
  v_settings public.workspace_settings;
BEGIN
  PERFORM app.require_workspace_manager(p_workspace_id);

  v_name := btrim(p_name);
  IF char_length(v_name) < 2 OR char_length(v_name) > 80 THEN
    RAISE EXCEPTION 'invalid_workspace_name' USING ERRCODE = '22023';
  END IF;

  v_slug := app.slugify(p_slug);
  IF v_slug IS NULL OR char_length(v_slug) < 3 OR char_length(v_slug) > 60 THEN
    RAISE EXCEPTION 'invalid_slug' USING ERRCODE = '22023';
  END IF;
  IF v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'invalid_slug' USING ERRCODE = '22023';
  END IF;
  IF app.is_reserved_workspace_slug(v_slug) THEN
    RAISE EXCEPTION 'reserved_slug' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.workspaces w
    WHERE w.slug = v_slug AND w.id IS DISTINCT FROM p_workspace_id
  ) THEN
    RAISE EXCEPTION 'slug_taken' USING ERRCODE = '23505';
  END IF;

  v_phone := app.normalize_phone(p_business_phone);
  IF p_business_phone IS NOT NULL AND btrim(p_business_phone) <> '' AND v_phone IS NULL THEN
    RAISE EXCEPTION 'invalid_phone' USING ERRCODE = '22023';
  END IF;

  v_email := nullif(lower(btrim(coalesce(p_business_email, ''))), '');
  v_instagram := nullif(btrim(regexp_replace(coalesce(p_instagram, ''), '^@+', '')), '');
  v_postal := regexp_replace(coalesce(p_postal_code, ''), '\D', '', 'g');
  IF v_postal = '' THEN
    v_postal := NULL;
  END IF;
  v_state := nullif(upper(btrim(coalesce(p_state, ''))), '');

  IF p_logo_path IS NOT NULL AND split_part(p_logo_path, '/', 1) IS DISTINCT FROM p_workspace_id::text THEN
    RAISE EXCEPTION 'invalid_logo_path' USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.bypass_protected_columns', 'on', true);

  UPDATE public.workspaces
  SET name = v_name,
      slug = v_slug,
      updated_at = clock_timestamp()
  WHERE id = p_workspace_id
  RETURNING * INTO v_workspace;

  UPDATE public.workspace_settings
  SET business_phone = v_phone,
      business_email = v_email,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      address = nullif(btrim(coalesce(p_address, '')), ''),
      city = nullif(btrim(coalesce(p_city, '')), ''),
      state = v_state,
      postal_code = v_postal,
      instagram = v_instagram,
      timezone = coalesce(nullif(btrim(coalesce(p_timezone, '')), ''), 'America/Sao_Paulo'),
      logo_path = CASE
        WHEN p_clear_logo THEN NULL
        WHEN p_logo_path IS NOT NULL THEN p_logo_path
        ELSE logo_path
      END,
      updated_at = clock_timestamp()
  WHERE workspace_id = p_workspace_id
  RETURNING * INTO v_settings;

  RETURN jsonb_build_object(
    'workspace_id', v_workspace.id,
    'name', v_workspace.name,
    'slug', v_workspace.slug,
    'timezone', v_settings.timezone
  );
END;
$function$

CREATE OR REPLACE FUNCTION app.workspace_timezone(p_workspace_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE
  v_tz text;
BEGIN
  SELECT s.timezone INTO v_tz
  FROM public.workspace_settings s
  WHERE s.workspace_id = p_workspace_id;

  IF v_tz IS NULL OR btrim(v_tz) = '' THEN
    RETURN app.product_timezone();
  END IF;
  RETURN v_tz;
END;
$function$
